_VERTEX_EVALUATORS = {
    ('PP', 10, 0): vertex_pp_t10_t0,
    ('PP', 0, 10): vertex_pp_t0_t10,
    ('PP', 10, 2): vertex_pp_t10_t2,
    ('PP', 2, 10): vertex_pp_t2_t10,
    ('PP', 10, 4): vertex_pp_t10_t4,
    ('PP', 4, 10): vertex_pp_t4_t10,
    ('PP', 10, 6): vertex_pp_t10_t6,
    ('PP', 6, 10): vertex_pp_t6_t10,
    ('GG', 10, 0): vertex_gg_t10_t0,
    ('GG', 0, 10): vertex_gg_t0_t10,
    ('GG', 10, 2): vertex_gg_t10_t2,
    ('GG', 2, 10): vertex_gg_t2_t10,
    ('GG', 10, 4): vertex_gg_t10_t4,
    ('GG', 4, 10): vertex_gg_t4_t10,
    ('GG', 10, 6): vertex_gg_t10_t6,
    ('GG', 6, 10): vertex_gg_t6_t10,
}

def has_gram(twice_level: int) -> bool:
    return int(twice_level) == 10

def has_vertex(component: str, left: int, right: int) -> bool:
    return (str(component), int(left), int(right)) in _VERTEX_EVALUATORS

def evaluate_gram(twice_level: int, momentum: float) -> np.ndarray:
    if int(twice_level) != 10:
        raise ValueError(f'no sparse Gram kernel at twice-level {twice_level}')
    return gram_t10(momentum)

def evaluate_vertex_parts(
    component: str,
    left_twice_level: int,
    right_twice_level: int,
    left_momentum: float,
    external_weight: complex,
    right_momentum: float,
) -> np.ndarray:
    key = (str(component), int(left_twice_level), int(right_twice_level))
    try:
        evaluator = _VERTEX_EVALUATORS[key]
    except KeyError as exc:
        raise ValueError(f'no sparse Ramond vertex kernel for {key}') from exc
    return evaluator(left_momentum, external_weight, right_momentum)

